import{_ as p,a0 as e,w as u,s,ao as a,I as r,x as n,a1 as o,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"【觀點】離了Linux，我就活不了！ | LCTT x X-CMD","titleTemplate":false,"description":"【觀點】離了Linux，我就活不了！ | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"【觀點】離了Linux，我就活不了！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"【觀點】離了Linux，我就活不了！ | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Why I can’t live without Linux","title":"【觀點】離了Linux，我就活不了！","tag":"201310","desc":""},"relativePath":"201310/Why I can’t live without Linux.md","filePath":"[post].md"}'),x={name:"201310/Why I can’t live without Linux.md"};function L(g,i,d,h,m,f){const t=e("Link");return u(),s("div",null,[i[13]||(i[13]=a('<h1 id="【觀點】離了linux-我就活不了" tabindex="-1">【觀點】離了Linux，我就活不了！ <a class="header-anchor" href="#【觀點】離了linux-我就活不了" aria-label="Permalink to “【觀點】離了Linux，我就活不了！”">​</a></h1><p>本文是為那些想要嘗試Linux的用户所寫，不過如果你已經是一名Linuxer，這裏也有一些你應該知道併為之自豪的事實。</p><p>討厭長篇大論？直接跳到最後的部分 “<strong>所有內容的整理</strong>”。</p><h3 id="為什麼我離不開linux" tabindex="-1">為什麼我離不開Linux？ <a class="header-anchor" href="#為什麼我離不開linux" aria-label="Permalink to “為什麼我離不開Linux？”">​</a></h3><p>我堅持這樣認為有我自己的原因。每隔幾天或幾個月，我重啓機器的時候，Linux的啓動過程都令我陶醉，而你也許會驚奇大多數操作系統並不是這樣的。</p><h3 id="先想像一些場景" tabindex="-1">先想像一些場景：### <a class="header-anchor" href="#先想像一些場景" aria-label="Permalink to “先想像一些場景：###”">​</a></h3><ol><li>你的機器經常崩潰。</li><li>它慢的令人髮指。</li><li>未經你允許，文件文件夾就自動建立/刪除。</li><li>機器莫名其妙的關閉。</li></ol><p>什麼狀況？真相只有一個！你中病毒了！而在Linux上，這樣的情況幾乎不會發生，甚至可以説&quot;根本沒有&quot;。😃</p><h3 id="為什麼-那又如何" tabindex="-1">為什麼/那又如何? <a class="header-anchor" href="#為什麼-那又如何" aria-label="Permalink to “為什麼/那又如何?”">​</a></h3><p>再想像一下，此時此刻，有成百上千個人正在為Linux編寫和檢查代碼，因此Linux一直在不斷的發展壯大，而幾乎全世界任何開發者都可以看到“代碼寫的是什麼？”，甚至指出是否哪裏有缺陷。</p><p><strong>1994年3月14日，Linux 1.0.0發佈，那時它只有176250行代碼。</strong></p><p><strong>到了2013年，Linux 3.10發佈時，它已經擁有15803499行代碼。</strong></p><p>另外一件事，是Linux的設計方式。不像其它一些操作系統，在Linux上，幾乎所有的複雜任務都需要root權限。例如在windows上，你進入某些系統文件夾，刪除了一些東西（為什麼你會這麼做呢？恩，也可能是病毒乾的 —— 它們確實會這麼幹。另外，我見過有些人為了釋放內存也會這麼做）。雖然當時什麼都沒發生，但是在你下一次啓動時...（這裏我不敢再往下描述了）。而在Linux上，任何時候當你試圖對系統乾點什麼，它都會提示你需要root密碼。那如果我就是root用户，而我又把系統搞砸了，怎麼辦？這是最壞的情況，但是仍然會有很多人指導你如何修復它。</p><p><strong>當你在街上摔倒的時候，一羣熱心的陌生人跑過來幫助你，你會有什麼感覺？愛和支持是無價的，你會感受的到！</strong></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/linux.png" alt=""></p><p><strong>穩定性</strong> - Linux機器可以無休止地運行下去。而通過一個簡單的“uptime”命令就可以讓你知道機器已經運行了多久。你永遠不需要關機，設備基本上都是熱插拔的。當然其它有的操作系統也可以報告運行時間，但是正如之前所説，Linux機器很少崩潰、藍屏、死機:D，除非你有意要搞砸它。</p><p>老話説得好 “<strong>Linux是很堅強的，除非，面對的是熊孩子！</strong>”</p><p>為了使機器遠離病毒、木馬，你需要做很多工作。一項研究表明，（在沒有任何防護措施的情況下，）連接到網絡之後，windows被入侵的平均時間是40分鐘，而在Linux上 - 你就像老闆一樣什麼都不用做，也就是説，在操作系統之外不需要安裝任何東西（，黑客也無法入侵）。</p><p><strong>安全性增強</strong> - Iptables。這個命令列工具用來設置防火牆是極好的。同樣，還有許多其它創新工具，比如*端口試探(port knocking)，chroot監獄（譯者注：chroot是在unix系統的一個操作，用於改變當前程序及其子進程真實的磁盤根目錄。改變根目錄後的程序無法訪問或命名正常路徑下的文件。這樣的根目錄就叫做&quot;chroot監獄（chroot jail,chroot prison)&quot;——來自維基百科 ）。</p><p><strong>SELinux</strong> - 如果設置執行了SELinux，即使你賦予某個文件完全訪問權限，其他人也無法訪問。</p><p>其它操作系統的源代碼僅僅是開發操作系統的人才可以看到，然而，對於Linux，每個人都可以訪問源代碼，這意味着發生錯誤的可能性很小。即使有一些錯誤發生，也可以及時修復。假如你受到了安全攻擊，開發操作系統的公司可能會用一週甚至一個月時間發佈一個補丁，這就意味着你的系統在這段時間仍然是脆弱的，但是Linux有不計其數的用户貢獻以及積極參與，這是非常好的，不是更好，而是最好。</p><p>如果，假設操作系統公司不修復bug呢？之後會怎麼樣？恭喜，你只能與bug為伴了。然而在linux下，有許多人修復bug，或者如果你是一個很好的程序員，也許你應該自己修復它並且將其貢獻到開源社區。 <strong>予人玫瑰，手留餘香！</strong></p><p>當有這樣一個免費且開源的優秀操作系統（Linux），為什麼你還要花錢買一個呢？當你決定投奔開源，學習的機會將會非常多。如果你是一個好的程序員，你應該拿到開源代碼，用你自己的方式構建它、設計它，按你自己的想法去使用它。</p><p><strong>全世界的開發人員用寶貴的時間和天才的頭腦為你帶來這一款“誰與爭鋒”的操作系統，它，就是Linux。</strong></p><p><strong>沒有crapware</strong>（譯者注： 附贈軟件，是一個貶義的俚語） - 操作系統是開源的，那其它工具呢？沒錯，有非常多的工具也是開源的，可以供用户使用。而在其它操作統統中，大部分軟件可能會要求你訂購服務、升級/購買。更糟糕的是，在用了幾天之後，你可能會發現這個玩意兒竟然只是30天的試用版。在這方面，Linux永遠不會讓你經歷這樣的沮喪。</p><p><strong>Linux還自帶了預裝應用程序，這樣，簡單幾步安裝之後就可以開始使用啦~</strong></p><p>在linux上，大部分驅動是內核自帶的，因此當使用一些硬件組件時你不必到處去尋找驅動程序。</p><p>如果你僅僅是一個普通的桌面用户，沒有多少事情要用命令列(CLI)來做 - Linux擁有各種桌面環境供你選擇，比如Gnome、KDE，沒錯，你可以稱呼它為 &quot;<strong>新一代桌面環境</strong>&quot;</p><p>你有沒有體驗過你的操作系統在運行一段時間後行動遲緩，而你只能通過重新安裝系統解決這個問題。恩，試試Linux吧，你會感到驚喜的。它很多年一如既往運行飛快並且反應靈敏，這樣，你就能專注於工作，而不用處理反應遲緩的操作系統。</p><p><strong>沒有後門(backdoor)</strong> - 當你不瞭解一個操作系統的源代碼時，你怎麼能確保它沒有後門呢？如果製造商公司留了一個隱秘的後門，當你連接到網絡的時候，這會讓你的隱私無所遁形。而在Linux上，任何東西都是開放的，因此沒有後門可以隱藏在操作系統裏。</p><p>這裏還要談另一個有趣的事：大部分使用windows的用户可能會有一個沮喪的事，就是當升級一些軟件或者操作系統的時候需要重啓機器。Linux不需要這樣的重啓。Linux是一個穩定的、完美運行多年也不需要重啓的系統。</p><p><strong>讓老機器品味重生</strong> - Linux甚至可以在很老的硬件上完美運行。不像其它的操作系統，需要升級硬件才能使用。</p><h3 id="所有內容的整理" tabindex="-1">所有內容的整理..### <a class="header-anchor" href="#所有內容的整理" aria-label="Permalink to “所有內容的整理..###”">​</a></h3><p>有免費的，為什麼還要使用非法的（盜版）</p><ul><li>賦予老機器第二春</li><li>開機很快</li><li>隨時更新</li><li>沒有垃圾軟件</li><li>沒有後門</li><li>沒有病毒</li><li>穩定性</li><li>兼容性</li><li>安全性能增強</li><li>運行快，反應靈敏</li><li>Linux不需要碎片整理</li><li>額，選擇Linux確實對環境有影響. (Google it)</li><li>自由無限的支持 - 論壇、郵件列表、IRC頻道</li><li>工作區特性 - 下一代桌面</li><li>沒有大麻煩</li><li>報告bug並得到修復</li><li>你不會感到孤單</li><li>我貢獻，我快樂，予人玫瑰，手留餘香</li><li>其它操作系統歸公司所有，微軟擁有Windows，蘋果擁有Mac-OS。Linux？我們擁有！</li></ul><p>總之,不僅僅是閲讀這篇文章，你一定要親自試試看，品味這種感覺 - 自由無價。</p><p>對我來説， <strong>linuxing 是沉思</strong>。 你呢？ 😃</p><p><strong>如果同意我的觀點，cheers！現在是該把Linux（這杯美酒）“傾入”你的杯中慢慢“品味”了。</strong></p><p><strong>如果不同意我的觀點，再一次cheers。你可以用各種方法來證明我是錯的。</strong></p><p>Google 一下&quot;linuxing urban dictionary”（譯者注：urban dictionary是一個專供網友發表一些特殊單詞或短語解釋的平台，這上面有許多正常詞典裏面查不到的詞條，即使是正常詞典裏面有的，在這裏也會有新的精闢解釋。網友們還可以對每一個詞條進行投票)。</p><p>感謝閲讀。來，笑一個 😄 Cheers！</p><hr>',42)),r("p",null,[i[1]||(i[1]=n("via: ",-1)),o(t,{href:"http://www.unixmen.com/cant-live-without-linux/"},{default:l(()=>[...i[0]||(i[0]=[n("http://www.unixmen.com/cant-live-without-linux/",-1)])]),_:1})]),r("p",null,[i[5]||(i[5]=n("譯者：",-1)),o(t,{href:"https://github.com/flsf"},{default:l(()=>[...i[2]||(i[2]=[n("flsf",-1)])]),_:1}),i[6]||(i[6]=n(" 校對：",-1)),o(t,{href:"https://github.com/carolinewuyan"},{default:l(()=>[...i[3]||(i[3]=[n("Caroline",-1)])]),_:1}),i[7]||(i[7]=n(" ，",-1)),o(t,{href:"http://blog.csdn.net/tinyeyeser"},{default:l(()=>[...i[4]||(i[4]=[n("Mr小眼兒",-1)])]),_:1})]),r("p",null,[i[10]||(i[10]=n("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[8]||(i[8]=[n("LCTT",-1)])]),_:1}),i[11]||(i[11]=n(" 原創翻譯，",-1)),o(t,{href:"http://linux.cn/"},{default:l(()=>[...i[9]||(i[9]=[n("Linux中國",-1)])]),_:1}),i[12]||(i[12]=n(" 榮譽推出",-1))])])}const C=p(x,[["render",L]]);export{b as __pageData,C as default};
